const CACHE='professor-maker-v4.17.1';
const ASSETS=['./','./index.html','./app.js','./advising-plan.js','./ui-motion.js','./campus-ui.css','./academic-portal.css','./postdoc-career.js','./checkpoints.js','./simulation-worker.js','./engine.js','./academic-calendar.js','./main-story.js','./balance.js','./workload.js','./grants.js','./funding.js','./impact.js','./travel.js','./venues.js','./relationship.js','./research-topics.js','./counseling.js','./names.js','./events.js','./monthly-choices.js','./dialogue.js','./stories.js','./ending-voice.js','./letter-archive.js','./ending-scenarios.js','./ending-context.js','./korean.js','./ending-evidence.js','./ending-collection.js','./disciplines.js','./cv.js','./cv-lab-scene.js','./cv.css','./statistics.js','./appearance.js','./student-pixel-art.js','./student-reaction.js','./weekly-scene.js','./lab-scene.js','./lab-season.js','./mini-room.js','./lab-equipment.js','./activity-motion.js','./activity-motion.css','./mobile.css','./recovery-art.js','./recovery-art.css','./ending-review.html','./ending-review.js','./ending-review.css','./ending-review-data.json','./analytics.js','./style.css','./logos.html','./icon.svg','./icon-192.png','./icon-512.png','./icon-maskable.png','./manifest.webmanifest','./assets/lab-mark.svg','./assets/lab-mark-monogram.svg','./assets/lab-mark-network.svg','./assets/lab-mark-letter.svg','./assets/fonts/NotoSansKR.woff2','./assets/fonts/SUITE.woff2'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS.map(u=>new Request(u,{cache:'reload'})))));self.skipWaiting();});
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('professor-maker-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(new URL(e.request.url).pathname.startsWith('/api/')||new URL(e.request.url).pathname.endsWith('/admin.html')||new URL(e.request.url).pathname.endsWith('/admin.js'))return;if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(caches.open(CACHE).then(async c=>{try{const res=await fetch(e.request.mode==='navigate'?e.request.url:e.request,{cache:'no-cache'});if(res.ok)await c.put(e.request,res.clone());return res;}catch{return await c.match(e.request)||(e.request.mode==='navigate'?await c.match('./index.html'):Response.error());}}));});
